create table if not exists public.okx_futures_credentials (user_id uuid primary key references auth.users(id) on delete cascade, encrypted_api_key text not null, encrypted_api_secret text not null, encrypted_passphrase text not null, api_key_last4 text not null, updated_at timestamptz not null default now()); alter table public.okx_futures_credentials enable row level security;
create table if not exists public.okx_futures_settings (user_id uuid primary key references auth.users(id) on delete cascade, connection_status text not null default 'not_connected' check (connection_status in ('not_connected','connected','error')), demo_trading boolean not null default true, auto_trade_enabled boolean not null default false, live_execution_enabled boolean not null default false, emergency_stop boolean not null default true, leverage integer not null default 1 check (leverage between 1 and 20), risk_percent numeric(5,2) not null default 0.50 check (risk_percent > 0 and risk_percent <= 2), max_daily_loss_pct numeric(5,2) not null default 2 check (max_daily_loss_pct > 0 and max_daily_loss_pct <= 5), max_open_positions integer not null default 3 check (max_open_positions between 1 and 10), api_key_last4 text, account_label text, account_mode text, last_checked_at timestamptz, last_error_code text, updated_at timestamptz not null default now()); alter table public.okx_futures_settings enable row level security;